mapper.select:
SELECT r.*,u.display_name patient_name,s.work_date,s.period FROM registration_request r
JOIN app_user u ON u.id=r.patient_id JOIN schedule s ON s.id=r.schedule_id
r.status=#{status}
ORDER BY r.id DESC LIMIT #{size} OFFSET #{offset}

SELECT id FROM registration_request WHERE status IN ('QUEUED','RETRY') AND next_attempt_at <= #{now}
AND expires_at > #{now} AND (last_delivered_at IS NULL OR last_delivered_at <= #{stale})
ORDER BY id LIMIT 100

SELECT t.*,u.display_name doctor_name FROM schedule_template t JOIN doctor d ON d.id=t.doctor_id JOIN app_user u ON u.id=d.user_id
t.doctor_id=#{doctor_id}
ORDER BY t.doctor_id,t.day_of_week,t.start_time,t.id LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM schedule_template WHERE doctor_id=#{doctor_id} AND day_of_week=#{day_of_week} AND enabled=TRUE
AND effective_from <= #{effective_to} AND effective_to >= #{effective_from}
AND (period=#{period} OR (start_time < #{end_time} AND end_time > #{start_time}))
 AND id <> #{id}
